INSERT OR IGNORE INTO leads (id,ghl_contact_id,name,email,phone,address,project_type,budget_hint,source,lifecycle,notes,closed_lost_reason,closed_lost_at,raw_payload,created_at) VALUES ('lead_cl_00001','ghl_100001','Cody Thomas','cody.thomas36@example.com','(602) 329-4843','3890 S Desert Cove Dr, Phoenix, AZ 85052','artificial_turf',2300000,'google','closed_lost','Wanted artificial turf and pet-grade turf. Budget around $23k. Site walk done February 2024. Chose another contractor — said our quote took too long to arrive. Wanted something low-maintenance for retirement.','competitor',1707264000000,NULL,1702944000000);
INSERT OR IGNORE INTO leads (id,ghl_contact_id,name,email,phone,address,project_type,budget_hint,source,lifecycle,notes,closed_lost_reason,closed_lost_at,raw_payload,created_at) VALUES ('lead_cl_00002','ghl_100002','Megan Nakamura','megan.nakamura3@example.com','(480) 353-6772','6911 E Saguaro Blvd, Chandler, AZ 85294','artificial_turf',2000000,'meta','closed_lost','Wanted artificial turf in Troon. Budget around $20k. Site walk done July 2023. Said ''maybe next season'' and never came back. Hosts a lot and wanted the yard ready for the holidays.','timing',1689033600000,NULL,1686614400000);
